def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if n == 0:
        return []
    vals = sorted(set(a))
    rank = {v: i + 1 for i, v in enumerate(vals)}
    m = len(vals)
    bit = [0] * (m + 1)

    def add(r: int, delta: int) -> None:
        while r <= m:
            bit[r] += delta
            r += r & -r

    def prefix(r: int) -> int:
        s = 0
        while r > 0:
            s += bit[r]
            r -= r & -r
        return s

    ans = [0] * n
    for i in range(n):
        r = rank[a[i]]
        ans[i] = prefix(m) - prefix(r)
        add(r, 1)
        if i - k >= 0:
            add(rank[a[i - k]], -1)
    return ans
